// Unit 2 homework: solving quadratics (formula, discriminant, complex numbers,
// completing the square, changing forms), systems with a line or a parabola,
// and quadratic inequalities. Generated by src/quadratics.js; `check` holds the
// answer key so scripts/verify_sympy.py confirms both the engine and the key.
import { complexProblem, cx, discProblem, interceptToStd, interceptToVertex, quadIneq2, quadProblem, solveProblem, stdToIntercept, stdToVertex, systemPointProblem, systemProblem, vertexToIntercept, vertexToStd } from '../../quadratics.js'

const R = String.raw
const fr = (n, d) => [n, d]
const withStep = (p, step) => ({ ...p, steps: [...p.steps, step] })
// equation lhs = rhs (descending coefficients), method, key roots (sympy), variable
const eq = (prompt, lhs, rhs, method, key, v = 'x') => solveProblem(prompt, lhs, rhs, method, key, v)
const disc = (prompt, lhs, rhs, D, v = 'x') => discProblem(prompt, lhs, rhs, D, v)
const cplx = (prompt, op, a, b, key) => complexProblem(prompt, op, cx(...a), b ? cx(...b) : null, key)
// system: each equation { x2, x, y, c } = 0; key: [[x, y], …]
const sys = (lines, eqs, key) => systemProblem(R`\begin{cases} ${lines.join(' \\\\ ')} \end{cases}`, eqs, key)
// is the point a solution? terms [[coef, xPower, yPower], …] = 0
const sysPt = (lines, terms, point, key) => systemPointProblem(R`\begin{cases} ${lines.join(' \\\\ ')} \end{cases}\ \text{at } (${point.join(', ')})`, lines.map((latex, i) => ({ latex, terms: terms[i] })), point, key)
const ineq = (lhs, rel, key, extra = {}) => ({ type: 'ineq', lhs, rel, key, ...extra })
const shade = (prompt, spec, rel, side) => ({ ...quadIneq2(prompt, spec, rel), exp: { dashed: rel.length === 1, side } })
const complexHand = (prompt, steps, answer, value, result) => ({ type: 'steps', prompt, steps, answer, check: { value, result } })

